module protocol::market_admin;

use std::type_name::TypeName;

use sui::clock::{Self, Clock};

use protocol::market;
use protocol::app::{AdminCap, ProtocolApp};
use protocol::market::MarketConfiguration;
use protocol::error;
use protocol::market::Market;

/// Event emitted when a new market is registered
public struct MarketRegisteredEvent has copy, drop {
    market_id: ID,
    market_type: TypeName,
    sender: address,
    timestamp_ms: u64,
}

/// Event emitted when a new market is updated
public struct MarketUpdatedEvent has copy, drop {
    config: MarketConfiguration,
    market_type: TypeName,
    sender: address,
    timestamp_ms: u64,
}

public struct MarketCircuiBreakChanged has copy, drop {
    market_type: TypeName,
    sender: address,
    timestamp_ms: u64,
    is_triggered: bool
}

public struct EmaSpotToleranceChanged has copy, drop {
    market_type: TypeName,
    asset_type: TypeName,
    sender: address,
    timestamp_ms: u64,
    tolerance: u64,
}

/// Register a new market type in the protocol
public fun register_market<MarketType>(
    _: &AdminCap,
    app: &mut ProtocolApp,
    market_config: MarketConfiguration,
    clock: &Clock,
    ctx: &mut TxContext,
): ID {
    let key = std::type_name::with_defining_ids<MarketType>();
    assert!(!app.is_market_registered<MarketType>(), error::market_already_exists());

    app.ensure_version_matches();

    let market = market::new<MarketType>(market_config, ctx);
    let market_id = object::id(&market);

    app.add_market<MarketType>(market_id);

    transfer::public_share_object(market);

    // Emit event
    sui::event::emit(MarketRegisteredEvent {
        market_id,
        market_type: key,
        sender: ctx.sender(),
        timestamp_ms: clock::timestamp_ms(clock),
    });

    market_id
}

/// Register a new market type in the protocol
public fun update_market<MarketType>(
    _: &AdminCap,
    app: &ProtocolApp,
    market: &mut Market<MarketType>,
    market_config: MarketConfiguration,
    clock: &Clock,
    ctx: &TxContext,
) {
    let key = std::type_name::with_defining_ids<MarketType>();

    app.validate_market<MarketType>(market);
    app.ensure_version_matches();

    market.update_market_config(market_config);

    // Emit event
    sui::event::emit(MarketUpdatedEvent {
        market_type: key,
        sender: ctx.sender(),
        config: market_config,
        timestamp_ms: clock::timestamp_ms(clock),
    });
}

public fun trigger_circuit_break<MarketType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    clock: &Clock,
    ctx: &TxContext,
) {
    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    market.trigger_circuit_break();

    let key = std::type_name::with_defining_ids<MarketType>();

    // Emit event
    sui::event::emit(MarketCircuiBreakChanged {
        market_type: key,
        sender: ctx.sender(),
        is_triggered: true,
        timestamp_ms: clock::timestamp_ms(clock),
    });
}

public fun discharge_circuit_break<MarketType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    clock: &Clock,
    ctx: &TxContext,
) {
    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    market.discharge_circuit_break();

    let key = std::type_name::with_defining_ids<MarketType>();

    // Emit event
    sui::event::emit(MarketCircuiBreakChanged {
        market_type: key,
        sender: ctx.sender(),
        is_triggered: false,
        timestamp_ms: clock::timestamp_ms(clock),
    });
}

/// Create a market configuration
public fun create_market_config(
    _: &AdminCap,
    self: &ProtocolApp,
    close_factor_numerator_percentage: u64,
    close_factor_bypass_min_value: u64,
): MarketConfiguration {
    // Validate parameters
    assert!(close_factor_numerator_percentage > 0, error::invalid_params_error());
    assert!(close_factor_numerator_percentage <= 100, error::invalid_params_error());
    assert!(close_factor_bypass_min_value != 0, error::invalid_params_error());

    self.ensure_version_matches();

    let close_factor = math::float::from_quotient(close_factor_numerator_percentage, 100);
    market::new_market_configuration(close_factor, close_factor_bypass_min_value)
}

public fun update_market_ema_spot_tolerance<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    tolerance_bps: u64,
    clock: &Clock,
    ctx: &TxContext,
) {
    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    market.set_ema_spot_tolerance<MarketType, CoinType>(tolerance_bps);

    sui::event::emit(EmaSpotToleranceChanged {
        market_type: std::type_name::with_defining_ids<MarketType>(),
        asset_type: std::type_name::with_defining_ids<CoinType>(),
        sender: ctx.sender(),
        timestamp_ms: clock.timestamp_ms(),
        tolerance: tolerance_bps,
    });
}

